def extract_objects(filepath):
    with open(filepath) as f:
        text = f.read()
    books = []
    pattern = r'\{([^{}]*?)\}'
    matches = re.findall(pattern, text, re.DOTALL)
    for match in matches:
        obj_str = '{' + match + '}'
        obj_str = re.sub(r'("(?:[^"\\]|\\.)*")\s*\n(\s*)"(\w)', r'\1,\n\2"\3', obj_str)
        obj_str = re.sub(r',\s*}', '}', obj_str)
        try:
